import{_ as e,o as r,c as t,a5 as o}from"./chunks/framework.CXvGqWf0.js";const m=JSON.parse('{"title":"漫画 · 第 69 话 性能预算与 CI 门禁","description":"","frontmatter":{},"headers":[],"relativePath":"comics/quality/EP.69-performance-budget.md","filePath":"comics/quality/EP.69-performance-budget.md","lastUpdated":1793853676000}'),l={name:"comics/quality/EP.69-performance-budget.md"};function i(n,a,s,d,c,h){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="漫画-·-第-69-话-性能预算与-ci-门禁" tabindex="-1">漫画 · 第 69 话 性能预算与 CI 门禁 <a class="header-anchor" href="#漫画-·-第-69-话-性能预算与-ci-门禁" aria-label="Permalink to &quot;漫画 · 第 69 话 性能预算与 CI 门禁&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/quality/03-performance-budget">docs/quality/03-performance-budget.md</a> ｜ 原画：<a href="./EP.69-performance-budget.svg">EP.69-performance-budget.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>标签君</strong>：结构师。本话他发现内容站 LCP 从 2.1s 恶化到 4.3s，而 PR 全绿。</li><li><strong>码叔</strong>：老工程师。他主张把「可接受的最差体验」写成预算，接到 CI 上。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>排查发现首屏 JS 从 160KB 涨到 340KB：依赖升级引入整包 lodash，图表库同步加载进首屏。团队此前只看线上指标，发现时已过两周。码叔建立三层预算（资源、请求、指标），构建后统计 chunk 体积，超预算阻断合并；图表库改动态 <code>import()</code>，lodash 改按需导入。首屏 JS 回落到 165KB，LCP 回到 2.2s。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>没有预算时，「变慢」是一个只能靠感觉和线上告警发现的问题。PR 里看不到体积变化，评审也无法判断一次依赖升级的代价。等指标恶化再排查，已经浪费了两周。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>三层预算各有职责：资源预算约束交付物，请求预算约束连接成本，指标预算约束用户感受。资源与请求是可归因的输入，指标是最终输出。只定指标，超支时不知道是谁超的；只定资源，可能省了字节却仍然慢。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>码叔把预算写进仓库，CI 固定设备与网络档位，构建后统计 chunk 并贴 PR 评论；门禁分级——小幅超支告警，显著超支阻断。示例里拖动 JS 体积滑块可以观察预算判定，点击「实测长任务」则用 <code>PerformanceObserver(&#39;longtask&#39;)</code> 验证超过 50ms 的任务会阻塞输入。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>三层预算成组落地：资源、请求、指标，单看一层会漏。</li><li>单位与口径写清：压缩前 / 后、KB / KiB、实验室 / 现场。</li><li>用 P75 定目标，不要用平均值或拍脑袋的极限值。</li><li>分级门禁：小幅告警、显著阻断，保留合理弹性。</li><li>输出变化量与归因模块，比一个红叉更有行动力。</li><li>预算要定期复查，过期预算会逼团队绕过门禁。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：既然已经有线上 RUM 指标，为什么还要在 CI 里做体积预算？</p><p><strong>答</strong>：RUM 是事后证据，反馈周期以天计；体积预算是事前约束，在合入前就能拦住回退。两者互补：预算负责「不让问题进线上」，RUM 负责「验证真实用户是否真的变好」。只有 RUM 没有预算，团队每次都要等线上恶化才行动。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>拖动 JS / 图片 / 请求数滑块，观察 PASS → WARN → FAIL 的判定变化：<a href="./../../examples/quality/03-performance-budget">examples/quality/03-performance-budget</a></li><li>点击「实测长任务」，在控制台与面板中确认 120ms 阻塞被识别为长任务。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 70 话《兼容矩阵与渐进增强兜底》——增强能力用错位置，旧环境会直接坏掉。</p>',22)])])}const p=e(l,[["render",i]]);export{m as __pageData,p as default};
